function cleanSeries(item) {
  const json = item.json;
  const observations = json.observations || [];

  const valid = observations
    .filter(o => o.value !== "." && o.value !== null && o.value !== undefined)
    .map(o => ({
      date: o.date,
      value: Number(o.value)
    }))
    .filter(o => !Number.isNaN(o.value));

  if (valid.length < 2) {
    return null;
  }

  return {
    series_id: json.seriess?.[0]?.id || json.series_id || null,
    current: valid[0].value,
    previous: valid[1].value,
    change: Number((valid[0].value - valid[1].value).toFixed(4)),
    date: valid[0].date,
    previous_date: valid[1].date
  };
}

const seriesMap = {};

for (const item of items) {
  const cleaned = cleanSeries(item);
  if (!cleaned) continue;

  const obs = item.json.observations || [];
  const first = obs[0];

  // Fallback: infer series from node name if present, otherwise use item order later
  const seriesId =
    item.json.series_id ||
    item.json?.seriess?.[0]?.id ||
    item.json?.seriesId ||
    null;

  if (seriesId) {
    seriesMap[seriesId] = cleaned;
  }
}

// If series_id is not returned by FRED, map by item order
const ordered = items.map(cleanSeries).filter(Boolean);

const realYield = seriesMap.DFII10 || ordered[0];
const broadUsd = seriesMap.DTWEXBGS || ordered[1];
const twoYearYield = seriesMap.DGS2 || ordered[2];
const breakevenInflation = seriesMap.T10YIE || ordered[3];
const financialStress = seriesMap.STLFSI4 || ordered[4];
const creditStress = seriesMap.BAMLH0A0HYM2 || ordered[5];

function signalFromChange(change, bullishWhenFalling = true, threshold = 0) {
  if (change === null || change === undefined) return "neutral";
  if (Math.abs(change) <= threshold) return "neutral";

  if (bullishWhenFalling) {
    return change < 0 ? "bullish" : "bearish";
  }

  return change > 0 ? "bullish" : "bearish";
}

function scoreSignal(signal) {
  if (signal === "bullish") return 1;
  if (signal === "bearish") return -1;
  return 0;
}

const drivers = {
  real_yield: {
    label: "10Y real yield",
    ...realYield,
    signal: signalFromChange(realYield?.change, true, 0.005)
  },
  broad_usd: {
    label: "Broad USD index",
    ...broadUsd,
    signal: signalFromChange(broadUsd?.change, true, 0.02)
  },
  fed_expectations_proxy: {
    label: "2Y Treasury yield",
    ...twoYearYield,
    signal: signalFromChange(twoYearYield?.change, true, 0.005)
  },
  inflation_expectations: {
    label: "10Y breakeven inflation",
    ...breakevenInflation,
    signal: signalFromChange(breakevenInflation?.change, false, 0.005)
  },
  financial_stress: {
    label: "Financial stress index",
    ...financialStress,
    signal: signalFromChange(financialStress?.change, false, 0.005)
  },
  credit_stress: {
    label: "High-yield credit spread",
    ...creditStress,
    signal: signalFromChange(creditStress?.change, false, 0.005)
  }
};

const weights = {
  "24h": {
    real_yield: 0.30,
    broad_usd: 0.25,
    fed_expectations_proxy: 0.20,
    financial_stress: 0.15,
    credit_stress: 0.10
  },
  "72h": {
    real_yield: 0.30,
    broad_usd: 0.20,
    fed_expectations_proxy: 0.25,
    financial_stress: 0.15,
    credit_stress: 0.10
  },
  "7d": {
    real_yield: 0.25,
    broad_usd: 0.20,
    fed_expectations_proxy: 0.25,
    inflation_expectations: 0.10,
    financial_stress: 0.10,
    credit_stress: 0.10
  },
  "1m": {
    real_yield: 0.25,
    broad_usd: 0.15,
    fed_expectations_proxy: 0.25,
    inflation_expectations: 0.15,
    financial_stress: 0.10,
    credit_stress: 0.10
  }
};

function calculateHorizon(weightSet) {
  let score = 0;

  for (const [driver, weight] of Object.entries(weightSet)) {
    score += scoreSignal(drivers[driver].signal) * weight;
  }

  score = Number(score.toFixed(4));

  let direction = "Neutral";
  if (score > 0.25) direction = "Bullish";
  if (score < -0.25) direction = "Bearish";

  const conviction = Math.round(50 + Math.abs(score) * 50);

  return {
    direction,
    conviction: `${conviction}%`,
    raw_score: score
  };
}

return [
  {
    json: {
      asset: "Gold",
      generated_at: new Date().toISOString(),
      drivers,
      outlook: {
        "24h": calculateHorizon(weights["24h"]),
        "72h": calculateHorizon(weights["72h"]),
        "7d": calculateHorizon(weights["7d"]),
        "1m": calculateHorizon(weights["1m"])
      }
    }
  }
];

const raw = $json.text || $json.output || $json.message || $json;

let parsed;

if (typeof raw === 'string') {
  parsed = JSON.parse(raw);
} else {
  parsed = raw;
}

return [
  {
    json: {
      fileContent: JSON.stringify(parsed, null, 2)
    }
  }
];
